-- Section 2 closure: block-aware manual moves + block integrity report.
-- Reuses canonical batch move/upsert validators; no parallel rule engine.
create or replace function public.get_schedule_block_move_plan_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare r public.teacher_schedule%rowtype;v_pattern smallint[];v_len int;v_start int;v_moves jsonb;v_periods int;begin perform public.open_permission_context('schedule.edit');select * into r from public.teacher_schedule where id=p_schedule_id and active and institution_code=public.current_tenant_code();if not found then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_NOT_FOUND');end if;if r.locked then return jsonb_build_object('ok',false,'error','SCHEDULE_ROW_LOCKED');end if;if r.teacher_assignment_id is null then return jsonb_build_object('ok',false,'error','SCHEDULE_SEMANTIC_LINK_REQUIRED');end if;select public.normalize_schedule_block_pattern_v2(er.block_pattern,a.assigned_hours) into v_pattern from public.teacher_course_assignments a cross join lateral public.get_effective_schedule_rule_v2(a.class_course_requirement_id,a.id) er where a.id=r.teacher_assignment_id and a.institution_code=public.current_tenant_code();if coalesce((select max(x) from unnest(v_pattern) x),1)<=1 then return jsonb_build_object('ok',false,'error','NOT_BLOCK_ACTIVITY');end if;with ordered as(select ts.id,ts.period,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id) select min(o.period),count(*)::int into v_start,v_len from ordered o join target t on t.grp=o.grp;if v_len is null or not(v_len=any(v_pattern)) then return jsonb_build_object('ok',false,'error','BLOCK_COMPONENT_UNRESOLVED');end if;select periods_per_day into v_periods from public.get_active_schedule_time_profile();if p_period<1 or p_period+v_len-1>v_periods then return jsonb_build_object('ok',false,'error','BLOCK_TARGET_OUT_OF_RANGE');end if;if exists(select 1 from public.teacher_schedule x where x.active and x.institution_code=public.current_tenant_code() and x.teacher_assignment_id=r.teacher_assignment_id and x.weekday=p_weekday and x.period in(p_period-1,p_period+v_len) and x.id not in(with ordered as(select ts.id,ts.period,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id) select o.id from ordered o join target t on t.grp=o.grp)) then return jsonb_build_object('ok',false,'error','BLOCK_WOULD_MERGE');end if;with ordered as(select ts.id,ts.period,ts.classroom_id,ts.period-row_number() over(order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id=r.teacher_assignment_id and ts.weekday=r.weekday),target as(select grp from ordered where id=p_schedule_id),component as(select o.* from ordered o join target t on t.grp=o.grp) select jsonb_agg(jsonb_build_object('schedule_id',c.id,'weekday',p_weekday,'period',p_period+(c.period-v_start),'classroom_id',coalesce(p_classroom_id,c.classroom_id)) order by c.period) into v_moves from component c;return jsonb_build_object('ok',true,'assignment_id',r.teacher_assignment_id,'duration',v_len,'source_start',v_start,'moves',v_moves);end$$;
create or replace function public.preview_schedule_block_move_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare p jsonb;q jsonb;begin p:=public.get_schedule_block_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if not coalesce((p->>'ok')::boolean,false) then return p;end if;q:=public.preview_schedule_batch_move_v1(p->'moves');return q||jsonb_build_object('block',true,'duration',(p->>'duration')::int,'moves',p->'moves');end$$;
create or replace function public.move_schedule_block_v1(p_schedule_id uuid,p_weekday smallint,p_period smallint,p_classroom_id uuid default null) returns jsonb language plpgsql security definer set search_path=public as $$declare p jsonb;q jsonb;aid uuid;begin p:=public.get_schedule_block_move_plan_v1(p_schedule_id,p_weekday,p_period,p_classroom_id);if not coalesce((p->>'ok')::boolean,false) then raise exception '%',coalesce(p->>'error','BLOCK_MOVE_INVALID');end if;aid:=(p->>'assignment_id')::uuid;q:=public.move_schedule_slots_batch_v1(p->'moves');if not public.schedule_current_block_matches_phase3_v1(aid) then raise exception 'BLOCK_PATTERN_BROKEN';end if;return q||jsonb_build_object('block',true,'duration',(p->>'duration')::int);end$$;
create or replace function public.get_schedule_block_integrity_report_v1() returns table(teacher_assignment_id uuid,expected_pattern smallint[],actual_pattern smallint[],ok boolean) language sql stable security definer set search_path=public as $$with base as(select a.id teacher_assignment_id,public.normalize_schedule_block_pattern_v2(er.block_pattern,a.assigned_hours) expected_pattern from public.teacher_course_assignments a cross join lateral public.get_effective_schedule_rule_v2(a.class_course_requirement_id,a.id) er where a.institution_code=public.current_tenant_code()),runs as(select x.teacher_assignment_id,count(*)::smallint len from(select ts.teacher_assignment_id,ts.weekday,ts.period-row_number() over(partition by ts.teacher_assignment_id,ts.weekday order by ts.period)::integer grp from public.teacher_schedule ts where ts.active and ts.institution_code=public.current_tenant_code() and ts.teacher_assignment_id is not null)x group by x.teacher_assignment_id,x.weekday,x.grp),actual as(select teacher_assignment_id,array_agg(len order by len desc)::smallint[] actual_pattern from runs group by teacher_assignment_id) select b.teacher_assignment_id,b.expected_pattern,coalesce(a.actual_pattern,'{}'::smallint[]),public.schedule_current_block_matches_phase3_v1(b.teacher_assignment_id) from base b left join actual a using(teacher_assignment_id) where cardinality(b.expected_pattern)>0 and exists(select 1 from unnest(b.expected_pattern)x where x>1) order by b.teacher_assignment_id$$;
revoke all on function public.get_schedule_block_move_plan_v1(uuid,smallint,smallint,uuid) from public;revoke all on function public.preview_schedule_block_move_v1(uuid,smallint,smallint,uuid) from public;revoke all on function public.move_schedule_block_v1(uuid,smallint,smallint,uuid) from public;revoke all on function public.get_schedule_block_integrity_report_v1() from public;grant execute on function public.get_schedule_block_move_plan_v1(uuid,smallint,smallint,uuid) to authenticated;grant execute on function public.preview_schedule_block_move_v1(uuid,smallint,smallint,uuid) to authenticated;grant execute on function public.move_schedule_block_v1(uuid,smallint,smallint,uuid) to authenticated;grant execute on function public.get_schedule_block_integrity_report_v1() to authenticated;
